from math import fsum, sqrt
from numbers import Number

def _is_numeric(value):
    # bool is a subclass of int, but is not treated as numeric data here
    return isinstance(value, Number) and not isinstance(value, (bool, complex))

def most_correlated_columns(data):
    if not data or len(data) < 2:
        raise ValueError("data must contain at least two columns")

    names = list(data.keys())
    columns = []
    lengths = []

    for name in names:
        try:
            values = list(data[name])
        except TypeError:
            raise TypeError(f"column {name!r} must be a list of numbers")

        for v in values:
            if not _is_numeric(v):
                raise TypeError(f"column {name!r} contains non-numeric value: {v!r}")

        columns.append([float(v) for v in values])
        lengths.append(len(values))

    if len(set(lengths)) != 1:
        raise ValueError("all columns must have the same length")

    n = lengths[0]
    if n < 2:
        raise ValueError("need at least two data points per column")

    means = [fsum(col) / n for col in columns]
    centered = []
    variances = []

    for col, mean in zip(columns, means):
        c = [x - mean for x in col]
        var = fsum(x * x for x in c)
        centered.append(c)
        variances.append(var)

    best_pair = None
    best_abs = -1.0

    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            denom = sqrt(variances[i] * variances[j])
            if denom == 0:
                continue  # correlation undefined if either column is constant

            cov = fsum(a * b for a, b in zip(centered[i], centered[j]))
            corr = cov / denom

            if abs(corr) > best_abs:
                best_abs = abs(corr)
                best_pair = (names[i], names[j])

    if best_pair is None:
        raise ValueError("no pair has a defined Pearson correlation")

    return best_pair
