def fit_linear_regression(features, values):
    """Fit OLS linear regression with an intercept using the normal equations."""
    n = len(features)
    if n == 0:
        raise ValueError("at least one row is required")
    if len(values) != n:
        raise ValueError("features and values must have the same length")

    m = len(features[0])
    if any(len(row) != m for row in features):
        raise ValueError("all feature rows must have the same length")

    p = m + 1  # intercept column + feature columns

    # Design matrix X with a leading column of ones
    X = [[1.0] + [float(x) for x in row] for row in features]
    y = [float(v) for v in values]

    # Normal equations: A beta = b, where A = X^T X, b = X^T y
    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p

    for i in range(n):
        xi = X[i]
        yi = y[i]
        for j in range(p):
            b[j] += xi[j] * yi
            for k in range(p):
                A[j][k] += xi[j] * xi[k]

    # Gaussian elimination with partial pivoting on augmented matrix
    M = [A[i][:] + [b[i]] for i in range(p)]

    for col in range(p):
        pivot = max(range(col, p), key=lambda r: abs(M[r][col]))
        if M[pivot][col] == 0.0:
            raise ValueError("singular design matrix; cannot fit unique coefficients")
        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pivot_value = M[col][col]
        for r in range(col + 1, p):
            factor = M[r][col] / pivot_value
            if factor != 0.0:
                for c in range(col, p + 1):
                    M[r][c] -= factor * M[col][c]

    # Back substitution
    beta = [0.0] * p
    for i in range(p - 1, -1, -1):
        s = M[i][p]
        for j in range(i + 1, p):
            s -= M[i][j] * beta[j]
        beta[i] = s / M[i][i]

    return {
        'coefficients': [float(c) for c in beta[1:]],
        'intercept': float(beta[0])
    }
