import csv
import io
import re

_NUMBER_RE = re.compile(r'[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?')


def _convert_cell(value):
    if value is None or value == '':
        return None

    stripped = value.strip()
    if _NUMBER_RE.fullmatch(stripped):
        if any(ch in stripped for ch in '.eE'):
            return float(stripped)
        return int(stripped)

    return value


def merge_csv_texts(csv_texts):
    if not csv_texts:
        return []

    columns = []
    seen = set()
    result = []

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))

        # Find the first non-blank row as the header.
        header = None
        for row in reader:
            if row:
                header = row
                break

        if header is None:
            continue

        # Add any new columns, and give previous rows None for them.
        new_columns = []
        for col in header:
            if col not in seen:
                seen.add(col)
                columns.append(col)
                new_columns.append(col)

        if new_columns:
            for record in result:
                for col in new_columns:
                    record[col] = None

        # Process data rows.
        for row in reader:
            if not row:  # skip completely blank lines
                continue

            record = {col: None for col in columns}
            for i, col in enumerate(header):
                cell = row[i] if i < len(row) else None
                record[col] = _convert_cell(cell)

            result.append(record)

    return result
