import math

def letter_count_correlations(strings):
    if not strings:
        return None

    letters = sorted({ch for s in strings for ch in s})
    if not letters:
        return {}

    n = len(strings)
    counts = {ch: [s.count(ch) for s in strings] for ch in letters}

    total = {ch: sum(counts[ch]) for ch in letters}
    total_sq = {ch: sum(v * v for v in counts[ch]) for ch in letters}

    result = {}
    for x in letters:
        result[x] = {}
        for y in letters:
            if x == y or counts[x] == counts[y]:
                result[x][y] = 1.0
            else:
                s_xy = n * sum(a * b for a, b in zip(counts[x], counts[y])) - total[x] * total[y]
                ss_x = n * total_sq[x] - total[x] ** 2
                ss_y = n * total_sq[y] - total[y] ** 2
                result[x][y] = s_xy / math.sqrt(ss_x * ss_y)

    return result
