import csv
import io
import math

def normalize_numeric_columns(csv_text):
    """
    Parse CSV text with a header row and min-max scale every numeric column
    to [0, 1]. Non-numeric columns are returned unchanged as strings.

    Raises ValueError if no numeric columns are present.
    """
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text must contain a header row")

    if not header:
        raise ValueError("CSV text must contain a header row")

    width = len(header)
    rows = []

    for row in reader:
        if row == []:  # skip blank lines
            continue
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width:
            row = row[:width]
        rows.append(row)

    columns = [[] for _ in header]
    for row in rows:
        for i in range(width):
            columns[i].append(row[i])

    def is_numeric(values):
        if not values:
            return False
        for value in values:
            s = value.strip()
            if not s:
                return False
            try:
                num = float(s)
            except ValueError:
                return False
            if not math.isfinite(num):
                return False
        return True

    result = {}
    found_numeric = False

    for i, name in enumerate(header):
        values = columns[i]

        if is_numeric(values):
            found_numeric = True
            nums = [float(v.strip()) for v in values]
            lo = min(nums)
            hi = max(nums)

            if hi == lo:
                result[name] = [0.0] * len(nums)
            else:
                result[name] = [(x - lo) / (hi - lo) for x in nums]
        else:
            result[name] = list(values)

    if not found_numeric:
        raise ValueError("CSV data has no numeric columns")

    return result
