import csv
import io
import re
from datetime import date

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}")

def _parse_date(value):
    if not isinstance(value, str) or not _DATE_RE.fullmatch(value):
        raise ValueError(f"Invalid date {value!r}; expected YYYY-MM-DD")
    try:
        return date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f"Invalid date {value!r}; expected YYYY-MM-DD") from exc


def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    start = _parse_date(start_date)
    end = _parse_date(end_date)

    reader = csv.reader(io.StringIO(csv_text, newline=""))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text must contain a header row")

    try:
        date_idx = header.index(column_name)
    except ValueError:
        raise ValueError(f"Column {column_name!r} not found in CSV header")

    result = []

    for row in reader:
        if date_idx >= len(row):
            continue

        try:
            row_date = _parse_date(row[date_idx])
        except ValueError:
            continue

        if start <= row_date <= end:
            result.append(row)

    return result
