import csv
import io
import math


def _parse_number(value, context):
    if value is None:
        raise ValueError(f"Missing value in {context}")
    s = value.strip()
    if s == "":
        raise ValueError(f"Missing value in {context}")
    try:
        num = float(s)
    except (TypeError, ValueError):
        raise ValueError(f"Non-numeric value {value!r} in {context}")
    if not math.isfinite(num):
        raise ValueError(f"Non-finite value {value!r} in {context}")
    return num


def _read_csv(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("CSV input must be a string")

    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV input is empty")

    header = [col.strip() for col in header]
    rows = []
    for row in reader:
        if row:  # skip truly blank lines
            rows.append(row)
    return header, rows


def _solve_linear_system(A, b):
    n = len(A)
    M = [A[i][:] + [b[i]] for i in range(n)]

    for col in range(n):
        pivot_row = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot_row][col]) < 1e-12:
            raise ValueError("Cannot fit a unique linear regression (singular matrix)")

        if pivot_row != col:
            M[col], M[pivot_row] = M[pivot_row], M[col]

        pivot = M[col][col]
        for j in range(col, n + 1):
            M[col][j] /= pivot

        for r in range(n):
            if r != col:
                factor = M[r][col]
                if factor != 0.0:
                    for j in range(col, n + 1):
                        M[r][j] -= factor * M[col][j]

    return [M[i][n] for i in range(n)]


def _fit_ols(X, y):
    n = len(X)
    if n == 0:
        raise ValueError("Training CSV has no data rows")

    p = len(X[0])
    if n < p:
        raise ValueError("Not enough training rows to fit a unique linear regression")

    XtX = [[0.0] * p for _ in range(p)]
    Xty = [0.0] * p

    for i in range(p):
        for j in range(i, p):
            val = math.fsum(row[i] * row[j] for row in X)
            XtX[i][j] = val
            XtX[j][i] = val
        Xty[i] = math.fsum(row[i] * yv for row, yv in zip(X, y))

    return _solve_linear_system(XtX, Xty)


def predict_linear_regression(train_csv, test_csv, target):
    if not isinstance(target, str):
        raise ValueError("target must be a string")
    target = target.strip()

    train_header, train_rows = _read_csv(train_csv)
    test_header, test_rows = _read_csv(test_csv)

    if len(set(train_header)) != len(train_header):
        raise ValueError("Duplicate column names in train CSV header")
    if len(set(test_header)) != len(test_header):
        raise ValueError("Duplicate column names in test CSV header")
    if set(train_header) != set(test_header):
        raise ValueError("Train and test CSV headers must contain the same columns")
    if target not in train_header:
        raise ValueError(f"Target column {target!r} not found in train CSV header")
    if target not in test_header:
        raise ValueError(f"Target column {target!r} not found in test CSV header")

    target_idx = train_header.index(target)
    feature_indices = [i for i, name in enumerate(train_header) if name != target]
    feature_names = [train_header[i] for i in feature_indices]

    X = []
    y = []
    for row_num, row in enumerate(train_rows, start=2):
        if len(row) != len(train_header):
            raise ValueError(
                f"Train row {row_num} has {len(row)} columns, "
                f"expected {len(train_header)}"
            )

        features = [
            _parse_number(row[i], f"train row {row_num}, column {train_header[i]!r}")
            for i in feature_indices
        ]
        target_value = _parse_number(
            row[target_idx], f"train row {row_num}, target {target!r}"
        )

        X.append([1.0] + features)
        y.append(target_value)

    beta = _fit_ols(X, y)

    test_indices = [test_header.index(name) for name in feature_names]

    predictions = []
    for row_num, row in enumerate(test_rows, start=2):
        if len(row) > len(test_header):
            raise ValueError(
                f"Test row {row_num} has {len(row)} columns, "
                f"expected at most {len(test_header)}"
            )
        if feature_indices and len(row) <= max(test_indices):
            raise ValueError(f"Test row {row_num} is missing a feature value")

        features = [
            _parse_number(row[i], f"test row {row_num}, column {name!r}")
            for i, name in zip(test_indices, feature_names)
        ]

        pred = beta[0]
        for coef, value in zip(beta[1:], features):
            pred += coef * value

        predictions.append(float(pred))

    return predictions
