import csv
from io import StringIO

def normalize_csv_columns(csv_text):
    reader = csv.reader(StringIO(csv_text))
    header = next(reader, None)

    if header is None:
        return {}

    rows = []
    for row in reader:
        if row:  # skip blank lines
            rows.append([float(cell) for cell in row])

    if not rows:
        return {name: [] for name in header}

    n_cols = len(header)
    mins = [min(row[i] for row in rows) for i in range(n_cols)]
    maxs = [max(row[i] for row in rows) for i in range(n_cols)]

    result = {}
    for i, name in enumerate(header):
        span = maxs[i] - mins[i]
        if span == 0:
            result[name] = [0.0] * len(rows)
        else:
            result[name] = [(row[i] - mins[i]) / span for row in rows]

    return result
```

