from html.parser import HTMLParser


class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self._table_depth = 0
        self._target_depth = None
        self._current_row = None
        self._current_cell = None
        self._in_cell = False
        self._done = False

    @staticmethod
    def _class_value(attrs):
        for name, value in attrs:
            if name == "class":
                return value
        return None

    def handle_starttag(self, tag, attrs):
        if self._done:
            return

        if tag == "table":
            if self._target_depth is None and self._class_value(attrs) == "data-table":
                self._target_depth = self._table_depth + 1
            self._table_depth += 1

        elif tag == "tr":
            if self._target_depth is not None and self._table_depth == self._target_depth:
                self._close_row()
                self._current_row = []

        elif tag == "td":
            if (
                self._target_depth is not None
                and self._table_depth == self._target_depth
                and self._current_row is not None
            ):
                if self._in_cell:
                    self._close_cell()
                self._in_cell = True
                self._current_cell = []

    def handle_endtag(self, tag):
        if self._done:
            return

        if tag == "table":
            if self._target_depth is not None and self._table_depth == self._target_depth:
                self._close_row()
                self._done = True
                self._target_depth = None
            if self._table_depth > 0:
                self._table_depth -= 1

        elif tag == "tr":
            if self._target_depth is not None and self._table_depth == self._target_depth:
                self._close_row()

        elif tag == "td":
            if (
                self._target_depth is not None
                and self._table_depth == self._target_depth
                and self._in_cell
            ):
                self._close_cell()

    def handle_data(self, data):
        if self._done:
            return
        if self._in_cell and self._current_cell is not None:
            self._current_cell.append(data)

    def _close_cell(self):
        if self._in_cell and self._current_row is not None and self._current_cell is not None:
            self._current_row.append("".join(self._current_cell))
        self._in_cell = False
        self._current_cell = None

    def _close_row(self):
        if self._current_row is not None:
            if self._in_cell:
                self._close_cell()
            self.rows.append(self._current_row)
            self._current_row = None
            self._in_cell = False
            self._current_cell = None


def extract_data_table_rows(html):
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()
    parser._close_row()
    return parser.rows
