from html.parser import HTMLParser

_VOID_ELEMENTS = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr',
    'basefont', 'bgsound', 'frame', 'keygen', 'command'
}


class _Node:
    def __init__(self, tag, attrs=None):
        self.tag = tag
        self.attrs = dict(attrs or [])
        self.children = []

    def get_text(self):
        return ''.join(
            child if isinstance(child, str) else child.get_text()
            for child in self.children
        )


class _TreeParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node('#root')
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = _Node(tag, attrs)
        self.stack[-1].children.append(node)
        if tag not in _VOID_ELEMENTS:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        self.stack[-1].children.append(_Node(tag, attrs))

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                break

    def handle_data(self, data):
        self.stack[-1].children.append(data)


def _has_class(node, cls):
    return cls in (node.attrs.get('class') or '').split()


def _find_first(node, tag, cls=None):
    for child in node.children:
        if isinstance(child, str):
            continue
        if child.tag == tag and (cls is None or _has_class(child, cls)):
            return child
        found = _find_first(child, tag, cls)
        if found is not None:
            return found
    return None


def extract_article_info(html):
    parser = _TreeParser()
    parser.feed(html)
    parser.close()

    result = []

    def walk(node):
        for child in node.children:
            if isinstance(child, str):
                continue

            if child.tag == 'div' and _has_class(child, 'container'):
                h1 = _find_first(child, 'h1')
                title = h1.get_text().strip() if h1 else 'No Title'

                date_span = _find_first(child, 'span', 'date')
                date = date_span.get_text().strip() if date_span else 'No Date'

                author_span = _find_first(child, 'span', 'author')
                author = author_span.get_text().strip() if author_span else 'No Author'

                result.append((title, date, author))

            walk(child)

    walk(parser.root)
    return result
