            # Ignore booleans, nulls, strings, etc.
            if isinstance(value, bool):
                continue
            if isinstance(value, int):
                values_by_key[key].append(value)
            elif isinstance(value, float) and math.isfinite(value):
                values_by_key[key].append(value)

