import math

def _is_missing(x):
    return x is None or x != x  # None or NaN

def merge_and_standardize(rows1, rows2):
    # Collect feature column names, preserving order.
    cols1 = []
    for row in rows1:
        for key in row:
            if key != 'id' and key not in cols1:
                cols1.append(key)

    cols2 = []
    for row in rows2:
        for key in row:
            if key != 'id' and key not in cols2:
                cols2.append(key)

    by_id1 = {row['id']: row for row in rows1}
    by_id2 = {row['id']: row for row in rows2}

    # Compute mean and population standard deviation for rows1 columns,
    # ignoring missing values.
    stats = {}
    for col in cols1:
        vals = [
            row[col]
            for row in rows1
            if col in row and not _is_missing(row[col])
        ]
        if not vals:
            stats[col] = (None, None)
        else:
            n = len(vals)
            mean = sum(vals) / n
            variance = sum((x - mean) ** 2 for x in vals) / n
            sd = math.sqrt(variance)
            stats[col] = (mean, sd)

    def standardize(col, value):
        if _is_missing(value):
            return None
        mean, sd = stats[col]
        if mean is None:
            return None
        if sd == 0:
            return 0.0
        return (value - mean) / sd

    result = []
    all_ids = sorted(set(by_id1) | set(by_id2))

    for id_ in all_ids:
        row1 = by_id1.get(id_)
        row2 = by_id2.get(id_)

        merged = {'id': id_}

        for col in cols1:
            if row1 is not None:
                merged[col] = standardize(col, row1.get(col))
            else:
                merged[col] = None

        for col in cols2:
            if row2 is not None:
                val = row2.get(col)
                merged[col] = None if _is_missing(val) else val
            else:
                merged[col] = None

        result.append(merged)

    return result
