    ncols = len(rows[0])
    stats = []

    for c in range(ncols):
        col = [row[c] for row in rows]

        # Constant column -> standard deviation is 0, so output zeros
        if all(x == col[0] for x in col):
            stats.append((col[0], 0.0))
        else:
            mean = sum(col) / n
            variance = sum((x - mean) ** 2 for x in col) / n
            std = math.sqrt(variance)
            stats.append((mean, std))

    return [
        [
            0.0 if stats[c][1] == 0.0 else (row[c] - stats[c][0]) / stats[c][1]
            for c in range(ncols)
        ]
        for row in rows
    ]
