def seasonal_decomposition(values, period, model):
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if not isinstance(period, int) or isinstance(period, bool) or period <= 0:
        raise ValueError("period must be a positive integer")

    values = list(values)
    n = len(values)

    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    half = period // 2
    trend = [None] * n

    # Centered moving average
    if period % 2 == 1:
        # Simple centered MA for odd periods
        for i in range(half, n - half):
            trend[i] = sum(values[i - half : i + half + 1]) / period
    else:
        # 2 x period centered MA for even periods
        for i in range(half, n - half):
            total = values[i - half] + values[i + half]
            total += 2 * sum(values[i - half + 1 : i + half])
            trend[i] = total / (2 * period)

    # Detrended series
    detrended = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if model == "additive":
                detrended[i] = values[i] - trend[i]
            else:
                detrended[i] = values[i] / trend[i]

    # Average detrended values for each seasonal phase
    sums = [0.0] * period
    counts = [0] * period
    for i, d in enumerate(detrended):
        if d is not None:
            phase = i % period
            sums[phase] += d
            counts[phase] += 1

    raw = [sums[p] / counts[p] for p in range(period)]
    mean_raw = sum(raw) / period

    # Normalize seasonal indices
    if model == "additive":
        seasonal_indices = [r - mean_raw for r in raw]
    else:
        if mean_raw == 0:
            raise ValueError("cannot normalize multiplicative seasonal indices to mean 1")
        seasonal_indices = [r / mean_raw for r in raw]

    seasonal = [seasonal_indices[i % period] for i in range(n)]

    # Residuals
    residual = [None] * n
    for i in range(n):
        if trend[i] is None:
            residual[i] = None
        elif model == "additive":
            residual[i] = values[i] - trend[i] - seasonal[i]
        else:
            residual[i] = values[i] / (trend[i] * seasonal[i])

    return {"trend": trend, "seasonal": seasonal, "residual": residual}
