def scale_table_columns(data):
    if not data:
        return {}

    columns = list(data.keys())
    n_rows = len(data[columns[0]])

    # Keep only rows with no None in any column
    keep = [
        i for i in range(n_rows)
        if all(data[col][i] is not None for col in columns)
    ]

    result = {}
    for col in columns:
        values = [data[col][i] for i in keep]

        if not values:
            result[col] = []
            continue

        lo = min(values)
        hi = max(values)

        if lo == hi:
            result[col] = [0.0] * len(values)
        else:
            result[col] = [(v - lo) / (hi - lo) for v in values]

    return result
