def column_linear_regression(rows, columns, target):
    """Fit an OLS linear regression with an intercept.

    Returns (coefficients, intercept), where coefficients are in the order
    of the columns excluding the target column.
    """
    if not rows:
        raise ValueError("rows is empty")

    try:
        target_idx = columns.index(target)
    except ValueError:
        raise ValueError("target is not one of the columns") from None

    if any(len(row) != len(columns) for row in rows):
        raise ValueError("each row must have the same length as columns")

    feature_indices = [i for i in range(len(columns)) if i != target_idx]

    n = len(rows)
    y = [float(row[target_idx]) for row in rows]
    X = [[float(row[i]) for i in feature_indices] for row in rows]

    p = len(feature_indices)
    y_mean = sum(y) / n

    if p == 0:
        return [], y_mean

    x_means = [sum(row[j] for row in X) / n for j in range(p)]

    # Center the data so the intercept can be recovered from the means.
    Xc = [[X[i][j] - x_means[j] for j in range(p)] for i in range(n)]
    yc = [yi - y_mean for yi in y]

    # Normal equations: A * beta = Xc^T * yc
    A = [
        [sum(Xc[i][r] * Xc[i][c] for i in range(n)) for c in range(p)]
        for r in range(p)
    ]
    b = [sum(Xc[i][j] * yc[i] for i in range(n)) for j in range(p)]

    # Solve A * beta = b using Gauss-Jordan elimination.
    m = p
    aug = [A[i][:] + [b[i]] for i in range(m)]
    scale = max((abs(v) for row in A for v in row), default=0.0)

    for col in range(m):
        pivot = max(range(col, m), key=lambda r: abs(aug[r][col]))
        if abs(aug[pivot][col]) <= 1e-12 * scale:
            raise ValueError("singular matrix: cannot fit unique OLS coefficients")
        if pivot != col:
            aug[col], aug[pivot] = aug[pivot], aug[col]

        pivot_val = aug[col][col]
        for j in range(col, m + 1):
            aug[col][j] /= pivot_val

        for r in range(m):
            if r != col:
                factor = aug[r][col]
                if factor != 0.0:
                    for j in range(col, m + 1):
                        aug[r][j] -= factor * aug[col][j]

    beta = [aug[i][m] for i in range(m)]
    intercept = y_mean - sum(beta[j] * x_means[j] for j in range(p))

    return [float(v) for v in beta], float(intercept)
