import math

def standardize_numeric_columns(data):
    result = {}

    for column, values in data.items():
        # Try to convert every value in the column to float.
        try:
            numbers = [float(v) for v in values]
        except (TypeError, ValueError):
            # Not a fully numeric column; leave it unchanged.
            result[column] = values
            continue

        n = len(numbers)
        if n == 0:
            result[column] = []
            continue

        mean = sum(numbers) / n
        variance = sum((x - mean) ** 2 for x in numbers) / n
        std = math.sqrt(variance)

        if std == 0:
            # Constant column: all z-scores are zero.
            result[column] = [0.0] * n
        else:
            result[column] = [(x - mean) / std for x in numbers]

    return result
