from collections import defaultdict, Counter
from fractions import Fraction

def association_chi_square(left, right):
    # Build inner join on id, preserving duplicate matches like a relational join.
    right_by_id = defaultdict(list)
    for id_, cat in right:
        right_by_id[id_].append(cat)

    joined = []
    for id_, left_cat in left:
        if id_ in right_by_id:
            for right_cat in right_by_id[id_]:
                joined.append((left_cat, right_cat))

    n = len(joined)
    if n == 0:
        return (0.0, 0)

    # Contingency table: rows = left categories, columns = right categories.
    table = defaultdict(Counter)
    for left_cat, right_cat in joined:
        table[left_cat][right_cat] += 1

    row_totals = {left_cat: sum(counts.values()) for left_cat, counts in table.items()}

    col_totals = Counter()
    for counts in table.values():
        col_totals.update(counts)

    left_cats = list(table.keys())
    right_cats = list(col_totals.keys())

    chi2 = Fraction(0, 1)

    # Pearson chi-square without continuity correction:
    # sum((observed - expected)^2 / expected)
    for left_cat in left_cats:
        for right_cat in right_cats:
            observed = table[left_cat].get(right_cat, 0)
            row_total = row_totals[left_cat]
            col_total = col_totals[right_cat]

            # expected = row_total * col_total / n
            # term = (n*observed - row_total*col_total)^2 / (n*row_total*col_total)
            chi2 += Fraction(
                (n * observed - row_total * col_total) ** 2,
                n * row_total * col_total
            )

    dof = (len(left_cats) - 1) * (len(right_cats) - 1)

    return (float(chi2), dof)
