from datetime import datetime
from zoneinfo import ZoneInfo

def publication_hour_stats(articles, timezone):
    if not articles:
        raise ValueError("articles list must not be empty")

    tz = ZoneInfo(timezone)
    grouped = {}

    for article in articles:
        if not isinstance(article, dict) or "category" not in article or "published_time" not in article:
            raise ValueError("each article must be a dict with 'category' and 'published_time'")

        category = article["category"]
        published = article["published_time"]

        if not isinstance(published, str):
            raise ValueError("'published_time' must be an ISO 8601 string")
        if published.endswith("Z"):
            published = published[:-1] + "+00:00"

        dt = datetime.fromisoformat(published)
        if dt.tzinfo is None:
            raise ValueError("'published_time' must include a UTC offset")

        hour = dt.astimezone(tz).hour

        if category not in grouped:
            grouped[category] = {"count": 0, "sum": 0, "min": hour, "max": hour}

        entry = grouped[category]
        entry["count"] += 1
        entry["sum"] += hour
        entry["min"] = min(entry["min"], hour)
        entry["max"] = max(entry["max"], hour)

    result = {}
    for category in sorted(grouped, key=str):
        entry = grouped[category]
        result[category] = {
            "count": entry["count"],
            "mean": entry["sum"] / entry["count"],
            "min": entry["min"],
            "max": entry["max"],
        }

    return result
