from collections import Counter

def _squared_distance(a, b):
    return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

def _centroid(cluster):
    n = len(cluster)
    return (sum(p[0] for p in cluster) / n, sum(p[1] for p in cluster) / n)

def cluster_unique_points(points, n_clusters):
    n_clusters = int(n_clusters)

    # Count duplicate occurrences in the original list
    counts = Counter(points)
    duplicates = {p: c for p, c in counts.items() if c > 1}

    # Work with distinct points only, sorted for deterministic behavior
    distinct = sorted(set(points))

    if n_clusters <= 0:
        k = 0
    else:
        k = min(n_clusters, len(distinct))

    if k == 0:
        clusters = []
    elif k == 1:
        clusters = [distinct]
    elif k == len(distinct):
        clusters = [[p] for p in distinct]
        clusters.sort()
    else:
        # Deterministic k-means: initial centroids are the first k distinct points
        centroids = distinct[:k]

        for _ in range(1000):
            assignments = [[] for _ in range(k)]
            for p in distinct:
                idx = min(range(k), key=lambda i: _squared_distance(p, centroids[i]))
                assignments[idx].append(p)

            new_centroids = []
            reinitialized = set()

            for cluster in assignments:
                if cluster:
                    new_centroids.append(_centroid(cluster))
                else:
                    # Re-seed an empty cluster at the farthest distinct point
                    candidates = [p for p in distinct if p not in reinitialized]
                    farthest = max(
                        candidates,
                        key=lambda p: min(_squared_distance(p, c) for c in centroids)
                    )
                    new_centroids.append(farthest)
                    reinitialized.add(farthest)

            if all(
                abs(new_centroids[i][0] - centroids[i][0]) < 1e-12 and
                abs(new_centroids[i][1] - centroids[i][1]) < 1e-12
                for i in range(k)
            ):
                centroids = new_centroids
                break

            centroids = new_centroids

        # Final assignment with the converged centroids
        assignments = [[] for _ in range(k)]
        for p in distinct:
            idx = min(range(k), key=lambda i: _squared_distance(p, centroids[i]))
            assignments[idx].append(p)

        clusters = [sorted(cluster) for cluster in assignments if cluster]
        clusters.sort()

    return duplicates, clusters
```

