def column_correlations(data):
    cols = list(data)
    if not cols:
        return {}

    n = len(next(iter(data.values())))
    result = {x: {} for x in cols}

    if n == 0:
        for x in cols:
            for y in cols:
                result[x][y] = 1.0 if x == y else float("nan")
        return result

    means = {c: sum(vals) / n for c, vals in data.items()}
    centered = {c: [v - means[c] for v in vals] for c, vals in data.items()}
    norms = {c: sum(v * v for v in centered[c]) ** 0.5 for c in cols}

    for x in cols:
        for y in cols:
            if x == y:
                result[x][y] = 1.0
            elif norms[x] == 0.0 or norms[y] == 0.0:
                result[x][y] = float("nan")
            else:
                cov = sum(a * b for a, b in zip(centered[x], centered[y]))
                result[x][y] = cov / (norms[x] * norms[y])

    return result
```

This computes the Pearson correlation for every pair of columns. Self-correlations are `1.0`; correlations involving a zero-variance column are returned as `nan` because they are undefined.

