import csv
import io
import math

def _to_number(value):
    """Return int/float if the string represents a finite number, else raise ValueError."""
    s = value.strip()
    if not s or '_' in s:
        raise ValueError(f"not numeric: {value!r}")

    try:
        return int(s)
    except ValueError:
        pass

    try:
        f = float(s)
        if math.isfinite(f):
            return f
    except ValueError:
        pass

    raise ValueError(f"not numeric: {value!r}")

def _is_numeric(value):
    try:
        _to_number(value)
        return True
    except ValueError:
        return False

def sort_csv_rows(csv_text, sort_by_column='title'):
    reader = csv.reader(io.StringIO(csv_text))

    # Find the first non-empty row as the header
    header = None
    for row in reader:
        if row:
            header = row
            break

    if header is None:
        return []

    # Remove a UTF-8 BOM if present on the first header field
    if header and header[0].startswith('\ufeff'):
        header[0] = header[0][1:]

    rows = []
    for row in reader:
        if not row:  # skip blank lines
            continue

        record = {}
        for i, col in enumerate(header):
            record[col] = row[i] if i < len(row) else ''
        rows.append(record)

    if sort_by_column not in header:
        raise ValueError(f"Column {sort_by_column!r} not found in CSV header")

    # Detect columns where every value is numeric
    numeric_columns = {
        col for col in header
        if rows and all(_is_numeric(rec[col]) for rec in rows)
    }

    # Convert numeric columns to int/float
    for rec in rows:
        for col in numeric_columns:
            rec[col] = _to_number(rec[col])

    return sorted(rows, key=lambda rec: rec[sort_by_column])
