from numbers import Number

def normalized_cumulative_sums(data):
    if not isinstance(data, dict):
        raise TypeError("data must be a dict")
    if not data or all(len(column) == 0 for column in data.values()):
        raise ValueError("data is empty")

    result = {}

    for column_name, values in data.items():
        cumulative = []
        running_total = 0

        for value in values:
            if not isinstance(value, Number) or isinstance(value, complex):
                raise TypeError(
                    f"non-numeric value in column {column_name!r}: {value!r}"
                )
            if value != value:  # NaN check
                raise ValueError(f"NaN value in column {column_name!r}")

            running_total += value
            cumulative.append(running_total)

        low = min(cumulative)
        high = max(cumulative)

        if high == low:
            result[column_name] = [0.0] * len(cumulative)
        else:
            result[column_name] = [
                float((x - low) / (high - low)) for x in cumulative
            ]

    return result
