import math

def standardize_by_group(records):
    """
    Standardize 'age' and 'income' to population z-scores within each 'id' group.
    Constant values within a group become 0.0.
    """
    required = ("id", "age", "income")
    records = list(records)

    # Validate required keys
    for rec in records:
        if not isinstance(rec, dict):
            raise ValueError("Each record must be a dict")
        for key in required:
            if key not in rec:
                raise ValueError(f"Record is missing required key: {key}")

    # Group records by id, preserving input record references
    groups = {}
    for rec in records:
        groups.setdefault(rec["id"], []).append(rec)

    # Compute mean and population standard deviation for each group/field
    stats = {}
    for gid, group in groups.items():
        stats[gid] = {}
        for field in ("age", "income"):
            values = [rec[field] for rec in group]
            mean = sum(values) / len(values)

            if all(v == values[0] for v in values):
                std = 0.0
            else:
                variance = sum((v - mean) ** 2 for v in values) / len(values)
                std = math.sqrt(variance)

            stats[gid][field] = (mean, std)

    # Build output in original input order
    result = []
    for rec in records:
        out = dict(rec)  # keeps 'id' and any other existing keys
        gid = rec["id"]

        for field in ("age", "income"):
            mean, std = stats[gid][field]
            if std == 0.0:
                z = 0.0
            else:
                z = (rec[field] - mean) / std
            out[field] = float(z)

        result.append(out)

    return result
