import math

def standardize_columns(rows):
    if not rows:
        return []

    n = len(rows)
    m = len(rows[0])

    if m == 0:
        return [[] for _ in rows]

    # Column means
    means = [math.fsum(row[j] for row in rows) / n for j in range(m)]

    # Population standard deviations per column
    stds = []
    for j in range(m):
        low = min(row[j] for row in rows)
        high = max(row[j] for row in rows)

        if low == high:
            stds.append(0.0)  # constant column
        else:
            var = math.fsum((row[j] - means[j]) ** 2 for row in rows) / n
            stds.append(math.sqrt(var))

    # Standardize each value
    return [
        [
            0.0 if stds[j] == 0.0 else float((row[j] - means[j]) / stds[j])
            for j in range(m)
        ]
        for row in rows
    ]
