import math
import numbers

def row_averages_and_correlations(data):
    # Validate input
    if not isinstance(data, list):
        raise ValueError("data must be a list of rows")
    if not data:
        return [], []

    if not all(isinstance(row, list) for row in data):
        raise ValueError("each row must be a list")

    ncols = len(data[0])
    if ncols == 0:
        raise ValueError("rows must contain at least one number")

    for row in data:
        if len(row) != ncols:
            raise ValueError("data must be rectangular")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, numbers.Real):
                raise ValueError("all values must be real numbers")

    nrows = len(data)

    # Row averages
    averages = [sum(row) / ncols for row in data]

    # Extract columns
    columns = [[row[c] for row in data] for c in range(ncols)]

    # Column means and standard deviations
    means = [sum(col) / nrows for col in columns]
    stds = [
        math.sqrt(math.fsum((x - mean) ** 2 for x in col))
        for col, mean in zip(columns, means)
    ]

    # Pearson correlation matrix
    corr = [[0.0] * ncols for _ in range(ncols)]
    for i in range(ncols):
        corr[i][i] = 1.0
        for j in range(i + 1, ncols):
            cov = math.fsum(
                (columns[i][k] - means[i]) * (columns[j][k] - means[j])
                for k in range(nrows)
            )
            denom = stds[i] * stds[j]
            if denom == 0.0:
                r = float("nan")   # undefined for constant columns
            else:
                r = cov / denom
                r = max(-1.0, min(1.0, r))
            corr[i][j] = r
            corr[j][i] = r

    return averages, corr
```

