from datetime import date, datetime, timedelta

def _to_day(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    # ISO date/datetime strings start with YYYY-MM-DD
    return date.fromisoformat(str(value).strip()[:10])

def daily_sales_totals(dates, sales):
    dates = list(dates)
    sales = list(sales)

    if len(dates) != len(sales):
        raise ValueError("dates and sales must have the same length")
    if not dates:
        raise ValueError("no records")

    totals = {}
    min_day = None
    max_day = None

    for d, amount in zip(dates, sales):
        day = _to_day(d)
        totals[day] = totals.get(day, 0) + amount

        if min_day is None or day < min_day:
            min_day = day
        if max_day is None or day > max_day:
            max_day = day

    result = []
    current = min_day
    while current <= max_day:
        result.append((current.isoformat(), totals.get(current, 0)))
        current += timedelta(days=1)

    return result
