import math

def standardized_tensor_product(P, T):
    if not P or not T:
        raise ValueError("P and T must be non-empty")

    if not all(isinstance(row, list) for row in P):
        raise ValueError("P must be a list of lists")

    m = len(P)
    k = len(P[0])

    if any(len(row) != k for row in P):
        raise ValueError("All rows of P must have the same length")
    if k == 0:
        raise ValueError("P is empty")

    if k != len(T):
        raise ValueError("P's number of columns must match T's first dimension")

    if not all(isinstance(t, list) for t in T):
        raise ValueError("T must be a 3D nested list")

    n = len(T[0])
    if any(len(t) != n for t in T):
        raise ValueError("T must be rectangular along its second axis")
    if n == 0:
        raise ValueError("T is empty")

    if not all(isinstance(row, list) for t in T for row in t):
        raise ValueError("T must be a 3D nested list")

    p = len(T[0][0])
    if any(len(row) != p for t in T for row in t):
        raise ValueError("T must be rectangular along its third axis")
    if p == 0:
        raise ValueError("T is empty")

    # Build the n-row table. Row j is P @ T[:, j, :], flattened row by row.
    table = [
        [
            float(sum(P[a][i] * T[i][j][b] for i in range(k)))
            for a in range(m)
            for b in range(p)
        ]
        for j in range(n)
    ]

    num_cols = m * p

    means = [0.0] * num_cols
    mins = [float("inf")] * num_cols
    maxs = [float("-inf")] * num_cols

    for row in table:
        for c, val in enumerate(row):
            means[c] += val
            if val < mins[c]:
                mins[c] = val
            if val > maxs[c]:
                maxs[c] = val

    for c in range(num_cols):
        means[c] /= n

    variances = [0.0] * num_cols
    for row in table:
        for c, val in enumerate(row):
            diff = val - means[c]
            variances[c] += diff * diff

    result = [[0.0] * num_cols for _ in range(n)]

    for c in range(num_cols):
        # Zero-variance columns become all zeros.
        if mins[c] == maxs[c]:
            continue

        std = math.sqrt(variances[c] / n)
        if std == 0.0:
            continue

        for r in range(n):
            result[r][c] = (table[r][c] - means[c]) / std

    return result
```

