def quartiles_of_string_groups(groups):
    # Flatten all string-encoded integers and sort them.
    nums = sorted(int(x) for group in groups for x in group)
    n = len(nums)

    if n == 0:
        raise ValueError("at least one integer is required")

    def quantile(p):
        # Linear interpolation: 0-based rank = (n - 1) * p
        rank = (n - 1) * p
        lo = int(rank)          # floor, since rank >= 0
        hi = lo + 1

        if hi >= n:
            return float(nums[lo])

        frac = rank - lo
        return float(nums[lo] + (nums[hi] - nums[lo]) * frac)

    return (quantile(0.25), quantile(0.50), quantile(0.75))
```

