def scale_by_group_with_histogram(ids, ages, incomes):
    if len(ids) == 0:
        raise ValueError("no rows")

    # First pass: find min and max for age and income in each group
    stats = {}
    for i, gid in enumerate(ids):
        if gid not in stats:
            stats[gid] = {
                "age_min": ages[i],
                "age_max": ages[i],
                "inc_min": incomes[i],
                "inc_max": incomes[i],
            }
        else:
            st = stats[gid]
            if ages[i] < st["age_min"]:
                st["age_min"] = ages[i]
            if ages[i] > st["age_max"]:
                st["age_max"] = ages[i]
            if incomes[i] < st["inc_min"]:
                st["inc_min"] = incomes[i]
            if incomes[i] > st["inc_max"]:
                st["inc_max"] = incomes[i]

    scaled = []
    counts = [0] * 10

    # Second pass: scale in original row order and histogram scaled incomes
    for gid, age, income in zip(ids, ages, incomes):
        st = stats[gid]

        if st["age_max"] == st["age_min"]:
            scaled_age = 0.0
        else:
            scale = 1.0 / (st["age_max"] - st["age_min"])
            scaled_age = age * scale - st["age_min"] * scale

        if st["inc_max"] == st["inc_min"]:
            scaled_income = 0.0
        else:
            scale = 1.0 / (st["inc_max"] - st["inc_min"])
            scaled_income = income * scale - st["inc_min"] * scale

        scaled.append([scaled_age, scaled_income])

        bin_index = int(scaled_income * 10)
        if bin_index > 9:
            bin_index = 9
        elif bin_index < 0:
            bin_index = 0
        counts[bin_index] += 1

    return scaled, counts
