def _solve_linear_system(A, b):
    """Solve A x = b using Gauss-Jordan elimination with partial pivoting."""
    n = len(A)
    if n == 0:
        return []

    M = [A[i][:] + [b[i]] for i in range(n)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) < 1e-12:
            raise ValueError("singular matrix: predictors may be collinear or insufficient data")

        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pivot_value = M[col][col]
        for j in range(col, n + 1):
            M[col][j] /= pivot_value

        for r in range(n):
            if r != col:
                factor = M[r][col]
                if factor != 0.0:
                    for j in range(col, n + 1):
                        M[r][j] -= factor * M[col][j]

    return [M[i][n] for i in range(n)]


def fit_linear_regression(records, target='z'):
    """
    Fit ordinary least-squares linear regression with an intercept.

    Returns:
        (intercept, {predictor_key: coefficient})
    """
    if not records:
        raise ValueError("records must not be empty")
    if target not in records[0]:
        raise KeyError(f"target key {target!r} not found in records")

    predictor_keys = [key for key in records[0] if key != target]
    n = len(records)

    rows = []
    for record in records:
        row = {key: float(record[key]) for key in predictor_keys}
        row[target] = float(record[target])
        rows.append(row)

    y = [row[target] for row in rows]
    y_mean = sum(y) / n

    p = len(predictor_keys)
    if p == 0:
        return y_mean, {}

    means = {key: sum(row[key] for row in rows) / n for key in predictor_keys}

    # Center predictors and target for numerical stability.
    Xc = [[row[key] - means[key] for key in predictor_keys] for row in rows]
    yc = [value - y_mean for value in y]

    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p

    for i in range(p):
        for j in range(i, p):
            s = sum(Xc[r][i] * Xc[r][j] for r in range(n))
            A[i][j] = s
            A[j][i] = s
        b[i] = sum(Xc[r][i] * yc[r] for r in range(n))

    coefs = _solve_linear_system(A, b)

    coefficients = {key: coefs[i] for i, key in enumerate(predictor_keys)}
    intercept = y_mean - sum(
        coefs[i] * means[key] for i, key in enumerate(predictor_keys)
    )

    return intercept, coefficients
