from io import StringIO

def fill_missing_with_column_mean(csv_text):
    if not csv_text or not csv_text.strip():
        return {}

    rows = list(csv.reader(StringIO(csv_text)))
    if not rows:
        return {}

    header = rows[0]
    if not header:
        return {}

    # Normalize row lengths to the header length
    data_rows = []
    for row in rows[1:]:
        if len(row) < len(header):
            row = row + [""] * (len(header) - len(row))
        else:
            row = row[:len(header)]
        data_rows.append(row)

    result = {}

    for i, column in enumerate(header):
        values = [row[i] for row in data_rows]
        present = [v for v in values if v != ""]

        numbers = None
        if present:
            try:
                numbers = [float(v) for v in present]
            except (ValueError, OverflowError):
                numbers = None

        if numbers is not None:
            mean = sum(numbers) / len(numbers)
            result[column] = [float(v) if v != "" else mean for v in values]
        else:
            result[column] = [v if v != "" else None for v in values]

    return result
