import math

def encode_and_standardize(data, replacements):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    result = {}

    for col_name, values in data.items():
        # 1. Replace values in a single pass
        col = [replacements.get(v, v) for v in values]

        # 2. Encode columns containing strings as integer codes
        if any(isinstance(v, str) for v in col):
            levels = sorted(set(col))
            code = {val: i for i, val in enumerate(levels)}
            col = [code[v] for v in col]

        # 3. Standardize using sample standard deviation (ddof=1)
        n = len(col)
        if n == 0:
            result[col_name] = []
            continue

        mean = sum(col) / n

        if n == 1:
            result[col_name] = [0.0]
            continue

        variance = sum((x - mean) ** 2 for x in col) / (n - 1)
        std = math.sqrt(variance)

        if std == 0:
            result[col_name] = [0.0] * n
        else:
            result[col_name] = [(x - mean) / std for x in col]

    return result
