import math

def summarize_stock_column(column, data):
    columns = {
        'Open': 1,
        'High': 2,
        'Low': 3,
        'Close': 4,
        'Volume': 5,
    }

    if not isinstance(column, str) or column not in columns:
        raise ValueError(f"Invalid column name: {column!r}")

    idx = columns[column]
    values = []

    for row in data:
        if not isinstance(row, (list, tuple)) or len(row) != 6:
            raise ValueError("Each row must have exactly six entries")

        val = row[idx]
        if val is not None:
            values.append(float(val))

    values.sort()
    n = len(values)

    if n == 0:
        return {
            'count': 0,
            'mean': None,
            'std': None,
            'min': None,
            '25%': None,
            '50%': None,
            '75%': None,
            'max': None,
        }

    mean = sum(values) / n

    if n > 1:
        variance = sum((x - mean) ** 2 for x in values) / (n - 1)
        std = math.sqrt(variance)
    else:
        std = None  # sample standard deviation is undefined for a single value

    def quantile(p):
        # Linear interpolation: position = p * (n - 1)
        pos = (n - 1) * p
        lo = math.floor(pos)
        hi = math.ceil(pos)

        if lo == hi:
            return float(values[lo])

        frac = pos - lo
        return float(values[lo] * (1.0 - frac) + values[hi] * frac)

    return {
        'count': n,
        'mean': mean,
        'std': std,
        'min': float(values[0]),
        '25%': quantile(0.25),
        '50%': quantile(0.50),
        '75%': quantile(0.75),
        'max': float(values[-1]),
    }
