import math

def correlation_without_column(data, column):
    if not isinstance(data, dict):
        return None

    numeric_cols = {}

    for name, values in data.items():
        if name == column:
            continue
        if not isinstance(values, (list, tuple)) or len(values) == 0:
            continue
        if all(isinstance(v, (int, float)) for v in values):
            numeric_cols[name] = [float(v) for v in values]

    if not numeric_cols:
        return None

    names = list(numeric_cols.keys())

    means = {
        name: math.fsum(values) / len(values)
        for name, values in numeric_cols.items()
    }

    variances = {
        name: math.fsum((v - means[name]) ** 2 for v in values)
        for name, values in numeric_cols.items()
    }

    result = {name: {} for name in names}

    for i, x in enumerate(names):
        result[x][x] = 1.0
        for y in names[i + 1:]:
            cov = math.fsum(
                (a - means[x]) * (b - means[y])
                for a, b in zip(numeric_cols[x], numeric_cols[y])
            )
            denom = math.sqrt(variances[x] * variances[y])
            r = cov / denom if denom != 0 else math.nan
            result[x][y] = r
            result[y][x] = r

    return result
