def column_histograms(table):
    if not isinstance(table, dict) or not table:
        raise ValueError("table must be a non-empty dict")

    histograms = {}

    for name, values in table.items():
        if not isinstance(values, (list, tuple)) or not values:
            continue

        if not all(_is_number(v) for v in values):
            continue

        lo = min(values)
        hi = max(values)
        counts = [0] * 10

        if lo == hi:
            # All values equal the maximum, so they fall in the last bin.
            counts[9] = len(values)
        else:
            for v in values:
                idx = int((v - lo) * 10 / (hi - lo))
                if idx >= 10:
                    idx = 9
                elif idx < 0:
                    idx = 0
                counts[idx] += 1

        histograms[name] = counts

    if not histograms:
        raise ValueError("table has no numeric columns")

    return histograms
