import math
import re
from collections import Counter

def tfidf_scores_for_question_articles(titles, contents):
    picked_contents = []
    for title, content in zip(titles, contents):
        lower_title = title.lower()
        if 'how' in lower_title or 'what' in lower_title:
            picked_contents.append(content)

    if not picked_contents:
        return {}

    doc_counters = []
    for content in picked_contents:
        words = re.findall(r'\w{2,}', content.lower())
        doc_counters.append(Counter(words))

    n = len(doc_counters)

    df = Counter()
    for counter in doc_counters:
        df.update(counter.keys())

    idf = {
        word: math.log((1 + n) / (1 + df[word])) + 1
        for word in df
    }

    totals = {}
    for counter in doc_counters:
        vec = {word: count * idf[word] for word, count in counter.items()}
        norm = math.sqrt(sum(value * value for value in vec.values()))

        if norm == 0:
            continue

        for word, value in vec.items():
            totals[word] = totals.get(word, 0.0) + value / norm

    return totals
