def grade_report(students, subjects, grades):
    report = {}
    student_averages = []

    for name, row in zip(students, grades):
        student_grades = {
            subject: float(grade)
            for subject, grade in zip(subjects, row)
        }
        average = sum(row) / len(subjects) if subjects else 0.0
        student_grades['Average Grade'] = float(average)
        report[name] = student_grades
        student_averages.append(average)

    n = len(students)

    average_entry = {
        subject: (sum(grades[i][j] for i in range(n)) / n if n else 0.0)
        for j, subject in enumerate(subjects)
    }
    average_entry['Average Grade'] = (
        sum(student_averages) / n if n else 0.0
    )

    report['Average'] = average_entry
    return report
