def replace_and_standardize(data, features, mapping):
    # Validate that all feature columns exist
    for feature in features:
        if feature not in data:
            raise ValueError(f"Feature column {feature!r} is missing from data")

    # Replace values throughout the whole table first
    replaced = {
        col: [mapping.get(value, value) for value in values]
        for col, values in data.items()
    }

    # Standardize each feature column to zero mean and unit variance
    for feature in features:
        values = replaced[feature]
        n = len(values)
        mean = sum(values) / n
        std = (sum((v - mean) ** 2 for v in values) / n) ** 0.5
        replaced[feature] = [(v - mean) / std for v in values]

    return replaced
