def column_histogram(records, column_name):
    if not records:
        raise ValueError(f"Column '{column_name}' does not exist")
    if any(column_name not in row for row in records):
        raise ValueError(f"Column '{column_name}' does not exist")

    values = [row[column_name] for row in records]

    # String columns: map each distinct string to its sorted rank.
    if all(isinstance(v, str) for v in values):
        distinct = sorted(set(values))
        rank = {v: i for i, v in enumerate(distinct)}
        values = [rank[v] for v in values]

    lo, hi = min(values), max(values)
    hist = [0] * 10

    # If min == max, every value is the maximum and goes in the last bin.
    if lo == hi:
        hist[9] = len(values)
        return hist

    span = hi - lo

    # Use exact integer arithmetic when possible (ints and mapped strings).
    if all(isinstance(v, int) for v in values):
        for v in values:
            idx = (v - lo) * 10 // span
            if idx >= 10:
                idx = 9
            hist[idx] += 1
    else:
        for v in values:
            idx = int((v - lo) * 10 / span)
            if idx >= 10:
                idx = 9
            hist[idx] += 1

    return hist
