```python
def fit_linear_regression(rows, targets):
    if not rows:
        raise ValueError("rows must not be empty")
    if len(rows) != len(targets):
        raise ValueError("rows and targets must have the same length")

    n = len(rows)
    p = len(rows[0])

    for row in rows:
        if len(row) != p:
            raise ValueError("all feature vectors must have the same length")

    # Center the data so we can solve for slopes first, then recover the intercept.
    x_means = [sum(row[j] for row in rows) / n for j in range(p)]
    y_mean = sum(targets) / n

    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p

    for row, y in zip(rows, targets):
        xc = [row[j] - x_means[j] for j in range(p)]
        yc = y - y_mean
        for i in range(p):
            b[i] += xc[i] * yc
            for j in range(p):
                A[i][j] += xc[i] * xc[j]

    coefficients = _solve_linear_system(A, b)
    intercept = y_mean - sum(coefficients[j] * x_means[j] for j in range(p))

    return coefficients, float(intercept)


def _solve_linear_system(A, b):
    n = len(A)
    if n == 0:
        return []

    M = [row[:] + [b[i]] for i, row in enumerate(A)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
        if M[pivot][col] == 0.0:
            raise ValueError("singular matrix")

        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        pivot_val = M[col][col]
        for j in range(col, n + 1):
            M[col][j] /= pivot_val

        for r in range(n):
            if r != col and M[r][col] != 0.0:
                factor = M[r][col]
                for j in range(col, n + 1):
                    M[r][j] -= factor * M[col][j]

    return [M[i][n] for i in range(n)]
