import json
import math


def _reject_json_constant(name):
    raise ValueError(f"Invalid JSON constant: {name}")


def boxplot_stats_at_path(json_data, key_path):
    if not isinstance(json_data, (str, bytes, bytearray)):
        raise ValueError("json_data must be a JSON string")

    try:
        data = json.loads(json_data, parse_constant=_reject_json_constant)
    except ValueError as exc:
        raise ValueError(f"Malformed JSON: {exc}") from exc

    current = data
    for key in key_path:
        if not isinstance(current, dict):
            raise KeyError(key)
        if key not in current:
            raise KeyError(key)
        current = current[key]

    if not isinstance(current, str):
        raise ValueError("Value at path must be a string")

    tokens = current.split(',')
    numbers = []

    for token in tokens:
        token = token.strip()
        if token == "":
            raise ValueError("Data string is empty or contains an empty value")
        try:
            value = float(token)
        except ValueError:
            raise ValueError(f"Data string contains non-numeric value: {token!r}")
        if not math.isfinite(value):
            raise ValueError(f"Data string contains non-finite value: {token!r}")
        numbers.append(value)

    if not numbers:
        raise ValueError("Data string is empty")

    numbers.sort()

    def quantile(q):
        n = len(numbers)
        pos = (n - 1) * q
        lower = math.floor(pos)
        upper = math.ceil(pos)
        if lower == upper:
            return numbers[lower]
        frac = pos - lower
        return numbers[lower] + frac * (numbers[upper] - numbers[lower])

    q1 = quantile(0.25)
    median = quantile(0.5)
    q3 = quantile(0.75)

    iqr = q3 - q1
    lower_fence = q1 - 1.5 * iqr
    upper_fence = q3 + 1.5 * iqr

    inliers = [x for x in numbers if lower_fence <= x <= upper_fence]
    outliers = sorted(x for x in numbers if x < lower_fence or x > upper_fence)

    return {
        'q1': q1,
        'median': median,
        'q3': q3,
        'whisker_low': min(inliers),
        'whisker_high': max(inliers),
        'outliers': outliers,
    }
