import xml.etree.ElementTree as ET

def xml_to_dict(s):
    if not isinstance(s, str) or not s.strip():
        raise ValueError("input must be a non-empty XML string")

    root = ET.fromstring(s)
    return {root.tag: _element_to_value(root)}


def _element_to_value(elem):
    children = list(elem)
    attrs = elem.attrib

    # Collect all text inside this element, including text after child elements.
    text_parts = []
    if elem.text:
        text_parts.append(elem.text)
    for child in children:
        if child.tail:
            text_parts.append(child.tail)
    text = ''.join(text_parts)

    # Leaf element with no attributes: text only, or None if empty.
    if not attrs and not children:
        return text if text else None

    result = {}

    for name, value in attrs.items():
        result['@' + name] = value

    for child in children:
        value = _element_to_value(child)
        tag = child.tag

        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(value)
            else:
                result[tag] = [existing, value]
        else:
            result[tag] = value

    if text:
        result['#text'] = text

    return result
