```python
def dbscan_cluster_labels(points):
    n = len(points)
    eps_sq = 3.0 * 3.0   # eps = 3, compare squared distances
    min_samples = 2

    labels = [-1] * n
    visited = [False] * n
    cluster_id = 0

    def dist_sq(p, q):
        return sum((a - b) * (a - b) for a, b in zip(p, q))

    def region_query(i):
        p = points[i]
        return [j for j in range(n) if dist_sq(p, points[j]) <= eps_sq]

    for i in range(n):
        if visited[i]:
            continue

        visited[i] = True
        neighbors = region_query(i)

        if len(neighbors) < min_samples:
            labels[i] = -1
            continue

        # Start a new cluster
        labels[i] = cluster_id
        seeds = neighbors[:]
        in_seeds = [False] * n
        for j in seeds:
            in_seeds[j] = True

        idx = 0
        while idx < len(seeds):
            j = seeds[idx]
            idx += 1

            if not visited[j]:
                visited[j] = True
                j_neighbors = region_query(j)
                if len(j_neighbors) >= min_samples:
                    for nb in j_neighbors:
                        if not in_seeds[nb]:
                            in_seeds[nb] = True
                            seeds.append(nb)

            if labels[j] == -1:
                labels[j] = cluster_id

        cluster_id += 1

    return labels
