from datetime import date, timedelta

def _second_friday(year, month):
    first_day = date(year, month, 1)
    # Friday is weekday 4
    first_friday = first_day + timedelta(days=(4 - first_day.weekday()) % 7)
    return first_friday + timedelta(days=7)

def second_friday_sales_report(start_date, periods, categories, sales):
    year, month, day = map(int, start_date.split('-'))
    start = date(year, month, day)

    result = []
    sales_index = 0

    for _ in range(periods):
        # Find the next second Friday on or after start_date
        while True:
            candidate = _second_friday(year, month)
            if candidate >= start:
                break

            if month == 12:
                year, month = year + 1, 1
            else:
                month += 1

        report_date = candidate.isoformat()

        for category in categories:
            result.append((report_date, category, sales[sales_index]))
            sales_index += 1

        # Move to the next month for the next period
        if month == 12:
            year, month = year + 1, 1
        else:
            month += 1

    return result
