from html.parser import HTMLParser

def html_table_records(html, table_id):
    """Return rows of the HTML table with the given id as a list of dicts."""
    class _TableParser(HTMLParser):
        def __init__(self, wanted_id):
            super().__init__(convert_charrefs=True)
            self.wanted_id = wanted_id

            self.table_depth = 0
            self.target_found = False
            self.active_target = False
            self.target_depth = 0

            self.in_row = False
            self.row_cells = None
            self.in_cell = False
            self.cell_text = None

            self.headers = None
            self.records = []
            self.first_row_seen = False

        def _in_target_table(self):
            return self.active_target and self.table_depth == self.target_depth

        def handle_starttag(self, tag, attrs):
            tag = tag.lower()

            if tag == "table":
                self.table_depth += 1
                attrs_dict = dict(attrs)
                if not self.target_found and attrs_dict.get("id") == self.wanted_id:
                    self.target_found = True
                    self.active_target = True
                    self.target_depth = self.table_depth

            elif tag == "tr":
                if self._in_target_table() and not self.in_row:
                    self.in_row = True
                    self.row_cells = []

            elif tag in ("td", "th"):
                if self.in_row and self._in_target_table() and not self.in_cell:
                    self.in_cell = True
                    self.cell_text = []

        def handle_endtag(self, tag):
            tag = tag.lower()

            if tag == "table":
                if self.table_depth > 0:
                    self.table_depth -= 1
                if self.active_target and self.table_depth < self.target_depth:
                    self.active_target = False
                    self.in_row = False
                    self.in_cell = False
                    self.row_cells = None
                    self.cell_text = None

            elif tag == "tr":
                if self.in_row and self._in_target_table():
                    cells = self.row_cells or []

                    if not self.first_row_seen:
                        self.headers = cells
                        self.first_row_seen = True
                    else:
                        record = {}
                        for i, header in enumerate(self.headers or []):
                            record[header] = cells[i] if i < len(cells) else ""
                        self.records.append(record)

                    self.in_row = False
                    self.row_cells = None

            elif tag in ("td", "th"):
                if self.in_cell and self.in_row and self._in_target_table():
                    text = "".join(self.cell_text or []).strip()
                    if self.row_cells is not None:
                        self.row_cells.append(text)
                    self.in_cell = False
                    self.cell_text = None

        def handle_data(self, data):
            if self.in_cell:
                self.cell_text.append(data)

    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()

    if not parser.target_found:
        raise ValueError(f"No table with id {table_id!r}")

    return parser.records
```

