import math

def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    # Replace values using the mapping
    columns = {
        name: [mapping.get(value, value) for value in values]
        for name, values in data.items()
    }

    def pearson(xs, ys):
        n = len(xs)
        if n == 0:
            return float('nan')

        mean_x = sum(xs) / n
        mean_y = sum(ys) / n

        cov = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
        var_x = sum((x - mean_x) ** 2 for x in xs)
        var_y = sum((y - mean_y) ** 2 for y in ys)

        denom = math.sqrt(var_x * var_y)
        if denom == 0.0:
            return float('nan')

        return cov / denom

    names = list(columns.keys())
    result = {}

    for a in names:
        result[a] = {}
        for b in names:
            if a == b:
                result[a][b] = 1.0
            else:
                result[a][b] = pearson(columns[a], columns[b])

    return result
