import csv
import io
import math

def csv_mean_median(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    next(reader, None)  # skip header row

    values = []
    for row in reader:
        if not row:
            continue

        cell = row[0].strip()
        if not cell:
            continue

        try:
            num = float(cell)
        except ValueError:
            continue

        if not math.isfinite(num):  # ignore NaN / inf
            continue

        values.append(num)

    if not values:
        return (None, None)

    values.sort()
    n = len(values)
    mean = sum(values) / n

    if n % 2 == 1:
        median = values[n // 2]
    else:
        median = (values[n // 2 - 1] + values[n // 2]) / 2.0

    return (mean, median)
