from numbers import Real

def column_covariance(columns):
    if not columns:
        raise ValueError("table is empty: no columns")

    names = list(columns.keys())
    n = len(columns[names[0]])

    if n == 0:
        raise ValueError("table is empty: no rows")

    for name in names:
        values = columns[name]
        if len(values) != n:
            raise ValueError(f"column {name!r} has length {len(values)}, expected {n}")
        for value in values:
            if not isinstance(value, Real):
                raise TypeError(f"column {name!r} contains non-numeric value: {value!r}")

    if n < 2:
        raise ValueError("at least two rows are required")

    means = {name: sum(columns[name]) / n for name in names}

    result = {a: {} for a in names}
    for a in names:
        for b in names:
            cov = sum(
                (columns[a][i] - means[a]) * (columns[b][i] - means[b])
                for i in range(n)
            ) / (n - 1)
            result[a][b] = cov

    return result
