import math

def standardize_columns(data):
    if not data:
        return []

    n_rows = len(data)
    n_cols = len(data[0])

    if n_cols == 0:
        return [[] for _ in data]

    # First pass: column sums, minima, and maxima
    sums = [0.0] * n_cols
    mins = [float("inf")] * n_cols
    maxs = [float("-inf")] * n_cols

    for row in data:
        for j, value in enumerate(row):
            sums[j] += value
            if value < mins[j]:
                mins[j] = value
            if value > maxs[j]:
                maxs[j] = value

    means = [s / n_rows for s in sums]

    # Second pass: sum of squared deviations from the mean
    sq_sums = [0.0] * n_cols
    for row in data:
        for j, value in enumerate(row):
            diff = value - means[j]
            sq_sums[j] += diff * diff

    # Population standard deviation
    stds = []
    for j in range(n_cols):
        if mins[j] == maxs[j]:
            stds.append(0.0)  # no variation
        else:
            variance = sq_sums[j] / n_rows
            stds.append(math.sqrt(variance))

    # Build standardized rows
    result = []
    for row in data:
        new_row = []
        for j, value in enumerate(row):
            if stds[j] == 0.0:
                new_row.append(0.0)
            else:
                new_row.append((value - means[j]) / stds[j])
        result.append(new_row)

    return result
