import math
import re

def tfidf_matrix(documents):
    docs = list(documents)
    tokenized = [re.findall(r'[^\W_]+', doc.lower()) for doc in docs]

    words = sorted({word for toks in tokenized for word in toks})
    n = len(docs)

    df = {}
    for toks in tokenized:
        for word in set(toks):
            df[word] = df.get(word, 0) + 1

    idf = {
        word: math.log((1 + n) / (1 + df[word])) + 1
        for word in words
    }

    rows = []
    for toks in tokenized:
        counts = {}
        for word in toks:
            counts[word] = counts.get(word, 0) + 1

        vector = [counts.get(word, 0) * idf[word] for word in words]
        norm = math.sqrt(sum(x * x for x in vector))

        if norm > 0:
            vector = [x / norm for x in vector]

        rows.append(vector)

    return words, rows
