def standardize_with_row_means(data):
    if not data:
        return []

    n = len(data)
    columns = list(zip(*data))

    if not columns:
        return [[] for _ in data]

    means = [sum(col) / n for col in columns]
    stds = [
        (sum((x - mean) ** 2 for x in col) / n) ** 0.5
        for col, mean in zip(columns, means)
    ]

    result = []
    for row in data:
        standardized = [
            (value - mean) / std if std != 0 else 0.0
            for value, mean, std in zip(row, means, stds)
        ]
        row_mean = sum(standardized) / len(standardized)
        result.append(standardized + [row_mean])

    return result
