def complete_row_histogram(data, bins):
    cols = list(data)
    cleaned = {col: [] for col in cols}

    # Drop rows containing None in any column
    for row in zip(*(data[col] for col in cols)):
        if any(v is None for v in row):
            continue
        for col, v in zip(cols, row):
            cleaned[col].append(float(v))

    pooled = [v for col in cols for v in cleaned[col]]

    if not pooled:
        return cleaned, None

    lo = min(pooled)
    hi = max(pooled)

    if lo == hi:
        return cleaned, None

    if bins <= 0:
        raise ValueError("bins must be a positive integer")

    width = (hi - lo) / bins
    counts = [0] * bins

    for v in pooled:
        idx = int((v - lo) / width)
        if idx < 0:
            idx = 0
        elif idx >= bins:
            idx = bins - 1
        counts[idx] += 1

    return cleaned, counts
