def last_column_skewness(rows):
    if not rows or not rows[0]:
        raise ValueError("table must have at least one row and one column")

    values = [row[-1] for row in rows if row and row[-1] is not None]
    n = len(values)

    if n < 2:
        raise ValueError("at least two non-missing values are required")

    mean = sum(values) / n
    m2 = sum((x - mean) ** 2 for x in values) / n
    m3 = sum((x - mean) ** 3 for x in values) / n

    if m2 == 0:
        raise ValueError("skewness is undefined for a constant column")

    return m3 / (m2 ** 1.5)
