def normalize_columns(data):
    if not data:
        raise ValueError("data must not be empty")

    normalized = {}

    for column, values in data.items():
        for value in values:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"non-numeric value in column {column!r}: {value!r}")

        if not values:
            normalized[column] = []
            continue

        low = min(values)
        high = max(values)

        if low == high:
            normalized[column] = [0.0] * len(values)
        else:
            span = high - low
            normalized[column] = [(value - low) / span for value in values]

    return normalized
