def fruit_sales_box_stats(records):
    """
    Return box-plot statistics (min, Q1, median, Q3, max) for each fruit's sales.
    Quartiles use linear interpolation at position (n - 1) * q on the sorted values.
    """
    if not records:
        raise ValueError("records must not be empty")

    sales_by_fruit = {}
    for fruit, _day, sales in records:
        sales_by_fruit.setdefault(fruit, []).append(sales)

    def quantile(sorted_vals, q):
        n = len(sorted_vals)
        pos = (n - 1) * q
        lo = int(pos)
        hi = min(lo + 1, n - 1)
        frac = pos - lo
        return float(sorted_vals[lo] + (sorted_vals[hi] - sorted_vals[lo]) * frac)

    stats = {}
    for fruit, sales in sales_by_fruit.items():
        vals = sorted(sales)
        stats[fruit] = (
            quantile(vals, 0.0),
            quantile(vals, 0.25),
            quantile(vals, 0.5),
            quantile(vals, 0.75),
            quantile(vals, 1.0),
        )

    return stats
