import math

def standardize_columns(rows, scale_cols):
    if not rows:
        return []

    n = len(rows)
    result = [list(row) for row in rows]

    for col in set(scale_cols):
        values = [row[col] for row in rows]

        # No variation -> all zeros
        if min(values) == max(values):
            mean = values[0]
            std = 0.0
        else:
            mean = math.fsum(values) / n
            variance = math.fsum((x - mean) ** 2 for x in values) / n
            std = math.sqrt(variance)

        for i in range(n):
            if std == 0.0:
                result[i][col] = 0.0
            else:
                result[i][col] = (values[i] - mean) / std

    return result
