import math

def standardize_filtered(data, age, weight):
    if 'Age' not in data:
        raise KeyError('Age')
    if 'Weight' not in data:
        raise KeyError('Weight')

    ages = data['Age']
    weights = data['Weight']

    keep = [i for i in range(len(ages)) if ages[i] < age and weights[i] > weight]
    n = len(keep)

    columns = list(data.keys())

    if n == 0:
        return {col: [] for col in columns}

    result = {}
    for col in columns:
        kept = [data[col][i] for i in keep]
        mean = sum(kept) / n

        if all(v == kept[0] for v in kept):
            result[col] = [0.0] * n
        else:
            variance = sum((v - mean) ** 2 for v in kept) / n
            std = math.sqrt(variance)
            if std == 0.0:
                result[col] = [0.0] * n
            else:
                result[col] = [(v - mean) / std for v in kept]

    return result
