def highly_correlated_column_pairs(data, cols, threshold):
    if not 0 <= threshold <= 1:
        raise ValueError("threshold must be between 0 and 1")

    n = len(data)
    if n == 0 or len(cols) < 2:
        return []

    m = len(cols)
    columns = [[row[i] for row in data] for i in range(m)]

    stats = []
    for col in columns:
        mean = sum(col) / n
        variance = sum((x - mean) ** 2 for x in col)
        is_constant = max(col) == min(col)
        stats.append((col, mean, variance, is_constant))

    result = []
    for i in range(m):
        col_i, mean_i, var_i, const_i = stats[i]
        if const_i:
            continue

        for j in range(i + 1, m):
            col_j, mean_j, var_j, const_j = stats[j]
            if const_j:
                continue

            denom = (var_i * var_j) ** 0.5
            if denom == 0:
                continue

            cov = sum(
                (col_i[k] - mean_i) * (col_j[k] - mean_j)
                for k in range(n)
            )
            corr = cov / denom

            # Guard against tiny floating-point overshoot outside [-1, 1]
            if corr > 1.0:
                corr = 1.0
            elif corr < -1.0:
                corr = -1.0

            if abs(corr) > threshold:
                result.append((cols[i], cols[j]))

    return result
```

