def classical_seasonal_decomposition(values, period, model='additive'):
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    values = list(values)
    n = len(values)

    if period <= 0:
        raise ValueError("period must be positive")
    if n < 2 * period:
        raise ValueError("series must contain at least two full periods")

    m = period // 2
    trend = [None] * n

    # Centred moving average. For even periods use a 2 x period MA.
    if period % 2 == 1:
        for i in range(m, n - m):
            trend[i] = sum(values[i - m:i + m + 1]) / period
    else:
        for i in range(m, n - m):
            trend[i] = (
                sum(values[i - m:i + m]) +
                sum(values[i - m + 1:i + m + 1])
            ) / (2 * period)

    valid = list(range(m, n - m))

    raw_seasonal = [0.0] * period
    counts = [0] * period

    for i in valid:
        phase = i % period
        if model == 'additive':
            detrended = values[i] - trend[i]
        else:
            if trend[i] == 0:
                raise ValueError("multiplicative decomposition requires non-zero trend")
            detrended = values[i] / trend[i]
        raw_seasonal[phase] += detrended
        counts[phase] += 1

    for phase in range(period):
        raw_seasonal[phase] /= counts[phase]

    if model == 'additive':
        offset = sum(raw_seasonal) / period
        seasonal_factors = [s - offset for s in raw_seasonal]
    else:
        scale = sum(raw_seasonal) / period
        if scale == 0:
            raise ValueError("cannot normalize multiplicative seasonal component")
        seasonal_factors = [s / scale for s in raw_seasonal]

    seasonal = [seasonal_factors[i % period] for i in range(n)]

    resid = [None] * n
    for i in valid:
        if model == 'additive':
            resid[i] = values[i] - trend[i] - seasonal[i]
        else:
            denom = trend[i] * seasonal[i]
            if denom == 0:
                raise ValueError("multiplicative residual denominator is zero")
            resid[i] = values[i] / denom

    return {'trend': trend, 'seasonal': seasonal, 'resid': resid}
