def matrix_tensor_product(P, T):
    n = len(T)

    # Validate that every row of P has the same length as T's first dimension.
    if any(len(row) != n for row in P):
        raise ValueError("Each row of P must have length equal to len(T)")

    m = len(P)
    A = len(T[0]) if n > 0 else 0
    B = len(T[0][0]) if A > 0 else 0

    product = [
        [
            [
                sum(P[i][k] * T[k][a][b] for k in range(n))
                for b in range(B)
            ]
            for a in range(A)
        ]
        for i in range(m)
    ]

    sums = [[sum(vec) for vec in row] for row in product]

    return product, sums
```

Example:

```python
matrix_tensor_product(
    [[1, 2], [3, 4]],
    [[[1, 0], [0, 1]], [[2, 1], [1, 2]]]
)
# ([[[5, 2], [2, 5]], [[11, 4], [4, 11]]], [[7, 7], [15, 15]])
```

