from bisect import bisect_right

def standardize_columns(data):
    result = {}

    for name, values in data.items():
        n = len(values)

        if n == 0:
            result[name] = ([], [0] * 20)
            continue

        # If all values are equal, population std is 0; return zeros.
        if max(values) == min(values):
            z = [0.0] * n
        else:
            mean = sum(values) / n
            variance = sum((x - mean) ** 2 for x in values) / n
            std = variance ** 0.5
            if std == 0:
                z = [0.0] * n
            else:
                z = [(x - mean) / std for x in values]

        lo, hi = min(z), max(z)
        width = (hi - lo) / 20

        # 21 edges define 20 equal-width bins.
        edges = [lo + i * width for i in range(20)] + [hi]
        counts = [0] * 20

        for v in z:
            # bisect_right places an internal edge into the bin starting at that edge.
            idx = bisect_right(edges, v) - 1
            if idx < 0:
                idx = 0
            elif idx >= 20:
                idx = 19  # maximum goes in the last bin
            counts[idx] += 1

        result[name] = (z, counts)

    return result
