def temperature_month_day_grid(records):
    if not records:
        raise ValueError("records list is empty")

    required = ("Date", "Time", "Temperature")
    temps = {}

    for record in records:
        if not isinstance(record, dict) or any(key not in record for key in required):
            raise ValueError("each record must contain 'Date', 'Time', and 'Temperature'")

        try:
            date_parts = record["Date"].split("-")
            if len(date_parts) != 3:
                raise ValueError
            month = int(date_parts[1])
            day = int(date_parts[2])
            temp = float(record["Temperature"])
        except (AttributeError, IndexError, TypeError, ValueError) as exc:
            raise ValueError("invalid record") from exc

        temps[(month, day)] = temp

    months = sorted({m for m, _ in temps})
    days = sorted({d for _, d in temps})

    return [[temps.get((month, day)) for day in days] for month in months]
